import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts uppercase letters to lowercase (REQ-001)", () => {
    expect(slugify("HELLO")).toBe("hello");
    expect(slugify("MixedCase")).toBe("mixedcase");
    expect(slugify("UPPERCASE")).toBe("uppercase");
  });

  test("replaces spaces with hyphens (REQ-002)", () => {
    expect(slugify("hello world")).toBe("hello-world");
    expect(slugify("foo bar")).toBe("foo-bar");
  });

  test("replaces underscores with hyphens (REQ-002)", () => {
    expect(slugify("foo_bar")).toBe("foo-bar");
  });

  test("collapses multiple consecutive spaces into single hyphen (REQ-002)", () => {
    expect(slugify("foo   bar")).toBe("foo-bar");
    expect(slugify("foo     bar   baz")).toBe("foo-bar-baz");
  });

  test("collapses multiple consecutive underscores into single hyphen (REQ-002)", () => {
    expect(slugify("foo___bar")).toBe("foo-bar");
  });

  test("removes special characters (REQ-003)", () => {
    expect(slugify("hello, world!")).toBe("hello-world");
    expect(slugify("foo@bar.com")).toBe("foobarcom");
    expect(slugify("test#123")).toBe("test123");
    expect(slugify("test@example.com")).toBe("testexamplecom");
  });

  test("preserves letters, numbers, and hyphens (REQ-003)", () => {
    expect(slugify("abc-123")).toBe("abc-123");
    expect(slugify("test-123-xyz")).toBe("test-123-xyz");
  });

  test("collapses consecutive hyphens (REQ-004)", () => {
    expect(slugify("a--b")).toBe("a-b");
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("a----b")).toBe("a-b");
  });

  test("trims leading and trailing hyphens (REQ-005)", () => {
    expect(slugify("-hello-")).toBe("hello");
    expect(slugify("--foo--")).toBe("foo");
    expect(slugify("-a-b-")).toBe("a-b");
    expect(slugify("-leading-trailing-")).toBe("leading-trailing");
  });

  test("handles empty string edge cases (REQ-006)", () => {
    expect(slugify("!!!")).toBe("");
    expect(slugify("   ")).toBe("");
    expect(slugify("")).toBe("");
  });

  test("handles combined transformations", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify(" Foo__Bar ")).toBe("foo-bar");
    expect(slugify("Hello, World! A Beginner's Guide")).toBe("hello-world-a-beginners-guide");
    expect(slugify("Super-Fast USB_3.0 Drive!!!")).toBe("super-fast-usb-30-drive");
  });

  test("validates all requirements table examples", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify(" Foo__Bar ")).toBe("foo-bar");
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("UPPERCASE")).toBe("uppercase");
    expect(slugify("test@example.com")).toBe("testexamplecom");
    expect(slugify("  ")).toBe("");
    expect(slugify("!!!")).toBe("");
    expect(slugify("-leading-trailing-")).toBe("leading-trailing");
    expect(slugify("foo___bar   baz")).toBe("foo-bar-baz");
  });
});

